import {scoreRows,parseCSV,toCSV} from './core.mjs';
const $=id=>document.getElementById(id),pct=x=>(x*100).toFixed(1)+'%',escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let model,data,scored,queue=[],page=0,uploaded=false;
const names={overview:['Retention overview','Turn customer risk into a focused outreach plan.'],score:['Score customers','Explore one customer or bring a complete batch.'],evaluation:['Model evaluation','Understand the evidence behind each prediction.'],guide:['Project guide','The workflow, implementation and business interpretation.']};
function tab(key){if(!names[key])return;Object.keys(names).forEach(k=>$(k).hidden=k!==key);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===key));$('pageTitle').textContent=names[key][0];$('subtitle').textContent=names[key][1];$('error').hidden=true;}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>tab(b.dataset.tab));
function fail(e){$('error').textContent=e.message||String(e);$('error').hidden=false;}
function download(rows,name){const url=URL.createObjectURL(new Blob([toCSV(rows)],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function render(){const d=scored.filter(r=>$('contract').value==='all'||r.contract===$('contract').value),flagged=d.filter(r=>r.contact_recommended),average=d.length?d.reduce((s,r)=>s+r.churn_probability,0)/d.length:0;
$('stats').innerHTML=[['Customers',d.length.toLocaleString(),'Selected cohort'],['Flagged for contact',flagged.length.toLocaleString(),pct(model.threshold)+' cutoff'],['Mean predicted risk',d.length?pct(average):'—','30-day cancellation'],['Holdout ROC-AUC','0.788','Synthetic test cohort']].map(([label,value,sub])=>`<div class="metric"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`).join('');
$('bands').innerHTML=['Low','Medium','High'].map((band,i)=>{const n=d.filter(r=>r.risk_band===band).length;return `<div class="band-row"><span>${band}</span><div class="bar-track"><div class="bar-fill" style="width:${d.length?n/d.length*100:0}%;background:${['#238b73','#dfaf49','#d77863'][i]}"></div></div><b>${n}</b></div>`;}).join('');
$('focusText').textContent=`${flagged.length.toLocaleString()} customers meet the contact cutoff in this selection.`;$('capacityLabel').textContent=$('capacity').value+' customers';queue=flagged.slice(0,Number($('capacity').value));page=0;renderTable();}
function renderTable(){const pages=Math.max(1,Math.ceil(queue.length/10));page=Math.min(page,pages-1);$('queueSummary').textContent=`${queue.length} eligible customers within your selected capacity`;$('queue').innerHTML=queue.slice(page*10,page*10+10).map(r=>`<tr><td>${escape(r.customer_id)}</td><td>${escape(r.contract)}</td><td>${pct(r.churn_probability)}</td><td><span class="pill ${r.risk_band}">${r.risk_band}</span></td><td>${r.suggested_action}</td></tr>`).join('')||'<tr><td colspan="5">No eligible customers in this selection.</td></tr>';$('prev').disabled=page===0;$('next').disabled=page>=pages-1;$('pageInfo').textContent=`Page ${page+1} of ${pages}`;$('downloadQueue').disabled=!queue.length;}
$('contract').onchange=render;$('capacity').oninput=render;$('prev').onclick=()=>{page--;renderTable();};$('next').onclick=()=>{page++;renderTable();};$('downloadQueue').onclick=()=>download(queue,'retention_queue.csv');$('downloadScores').onclick=()=>download(scored,'customer_predictions.csv');
function loadBatch(rows,label){const result=scoreRows(rows,model);scored=result;uploaded=true;$('cohort').textContent=label;$('contract').value='all';$('downloadScores').disabled=false;render();$('uploadStatus').textContent=`${scored.length.toLocaleString()} customers scored. Open Overview to explore the new cohort.`;$('error').hidden=true;return {customers:scored.length,flagged:scored.filter(r=>r.contact_recommended).length};}
$('csv').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>10*1024*1024)throw Error('CSV exceeds the 10 MB limit.');loadBatch(parseCSV(await file.text()),'UPLOADED COHORT');}catch(e){fail(e);$('uploadStatus').textContent='Upload rejected. The previous cohort is unchanged.';}};
$('reset').onclick=()=>{scored=scoreRows(data.customers,model);uploaded=false;$('cohort').textContent='NOVEMBER 2025 · SAMPLE COHORT';$('csv').value='';$('uploadStatus').textContent='Sample cohort restored.';$('contract').value='all';$('error').hidden=true;render();};
function predictOne(row){const r=scoreRows([{...row,customer_id:'PREVIEW'}],model)[0];$('singleResult').innerHTML=`<strong>${pct(r.churn_probability)}</strong><p>${r.risk_band} risk · ${r.contact_recommended?'Eligible for contact':'Below contact cutoff'}</p><p><b>Suggested action:</b> ${r.suggested_action}</p>`;return {probability:r.churn_probability,risk:r.risk_band,action:r.suggested_action};}
$('single').onsubmit=e=>{e.preventDefault();try{predictOne(Object.fromEntries(new FormData(e.target)));$('error').hidden=true;}catch(e){fail(e);}};
async function start(){try{const responses=await Promise.all(['model.json','data.json'].map(p=>fetch(p)));for(const r of responses)if(!r.ok)throw Error('Could not load model data. Please reload.');[model,data]=await Promise.all(responses.map(r=>r.json()));scored=scoreRows(data.customers,model);render();$('downloadScores').disabled=false;
const m=data.metrics;$('evalStats').innerHTML=[['ROC-AUC',m.roc_auc.toFixed(3)],['Average precision',m.average_precision.toFixed(3)],['Precision',pct(m.precision)],['Recall',pct(m.recall)]].map(([k,v])=>`<div class="metric"><span>${k}</span><strong>${v}</strong><small>Untouched synthetic holdout</small></div>`).join('');
$('comparison').innerHTML='<div class="table-wrap"><table><thead><tr><th>Model</th><th>Average precision</th></tr></thead><tbody>'+data.comparison.map(r=>`<tr><td>${escape(r.model.replaceAll('_',' '))}</td><td>${r.average_precision.toFixed(3)}</td></tr>`).join('')+'</tbody></table></div>';
$('importance').innerHTML=data.importance.slice(0,5).map(r=>`<p style="margin-bottom:5px;font-size:14px">${escape(r.feature.replaceAll('_',' '))} <b style="float:right">${r.mean_ap_decrease.toFixed(3)}</b></p><div class="bar-track"><div class="bar-fill" style="width:${r.mean_ap_decrease/data.importance[0].mean_ap_decrease*100}%"></div></div>`).join('');$('loading').hidden=true;tab('overview');
if(document.modelContext?.registerTool){document.modelContext.registerTool({name:'score_churn_customers',title:'Score customer batch',description:'Score a batch with the same model as the CSV interface and show the resulting cohort in Overview. No contact is sent.',inputSchema:{type:'object',properties:{customers:{type:'array',minItems:1,maxItems:20000,items:{type:'object'}}},required:['customers'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:true},execute(input){if(!input||!Array.isArray(input.customers))throw Error('customers array is required');const result=loadBatch(input.customers,'SCORED COHORT');tab('overview');return result;}});}
}catch(e){$('loading').hidden=true;fail(e);}}
start();
